DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='team_boss_issue'; d:=replace(d,'ELSE SELECT word,meaning INTO w FROM public.words h WHERE grade=p.grade AND length(meaning)>0 ORDER BY random() LIMIT 1; END IF;','ELSIF p.grade BETWEEN 1 AND 6 THEN SELECT word,meaning INTO w FROM public.hs_words h WHERE grade=p.grade AND subject=''science'' AND length(meaning)>0 ORDER BY random() LIMIT 1; ELSE SELECT word,meaning INTO w FROM public.words h WHERE grade=p.grade AND length(meaning)>0 ORDER BY random() LIMIT 1; END IF;'); EXECUTE d; END $$;